'use strict';

// Student records remain in the native per-enrolment store; only a cosmetic theme can persist here.
let state={items:[],messages:[],hidden_keys:[],tasks:[]},view='Home',folder=[],showHidden=false,files=null,fileKind='file';
let supportReadLocal=new Set(),attachmentTarget='support',draftImages={support:'',bug:''};
let received=false,lockedOut=false,identity='',profilePhoto=null,menuOpen=false,lastPageHTML='',lastBannerHTML='',lastTaskRaw='',toastTimer;
let helpQuery='',helpCategory='';
let noteQuery='',appQuery='',mediaQuery='',noteForm='',noteSubject='',noteType='',noteAvailability='',appFilter='',noteLimit=120,appLimit=120;
let indexedItems=[],taskMap=new Map(),searchTimer,themePending=null,lastCatalogueKey='',activeSignature='',globalQuery='';
const paths={home:'M3 10 12 3l9 7v10H3z M9 20v-7h6v7',mail:'M3 5h18v14H3z M3 6l9 7 9-7',book:'M12 5c-3-2-6-2-9-1v15c3-1 6-1 9 1 3-2 6-2 9-1V4c-3-1-6-1-9 1z M12 5v15',apps:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',image:'M3 3h18v18H3z M3 17l6-6 4 4 3-3 5 5 M16 7h.01',device:'M3 4h18v13H3z M1 21h22 M9 17v4 M15 17v4',folder:'M3 7V4h6l3 3h9v13H3z',arrow:'M5 12h14 M14 7l5 5-5 5',back:'M19 12H5 M10 7l-5 5 5 5',sync:'M20 7a8 8 0 0 0-14-2L3 8 M3 3v5h5 M4 17a8 8 0 0 0 14 2l3-3 M21 21v-5h-5',help:'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18 M9 9a3 3 0 0 1 6 0c0 2-3 2-3 4 M12 17h.01',file:'M5 3h9l5 5v13H5z M14 3v5h5 M8 13h8 M8 17h6',music:'M9 18V5l12-2v13 M9 5l12-2 M9 17c-6-3-9 5-3 5 2 0 3-1 3-4 M21 15c-6-3-9 5-3 5 2 0 3-1 3-4',video:'M3 5h13v14H3z M16 10l5-3v10l-5-3',check:'M4 12l5 5L20 6',shield:'M12 3l9 4v5c0 5-5 8-9 10-4-2-9-5-9-10V7z M8 12l3 3 5-6',search:'M10.5 3a7.5 7.5 0 1 0 0 15 7.5 7.5 0 0 0 0-15 M16 16l5 5',sun:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8 M12 2v2 M12 20v2 M2 12h2 M20 12h2 M5 5l1.4 1.4 M17.6 17.6l1.4 1.4 M5 19l1.4-1.4 M17.6 6.4l1.4-1.4',moon:'M21 13a9 9 0 1 1-10-10 7 7 0 0 0 10 10',menu:'M4 6h16 M4 12h16 M4 18h16',close:'M6 6l12 12 M6 18 18 6',download:'M12 3v12 M7 10l5 5 5-5 M4 16v5h16v-5',clock:'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18 M12 7v5l3 2',wifi:'M3 8a15 15 0 0 1 18 0 M6 12a10 10 0 0 1 12 0 M9 16a5 5 0 0 1 6 0 M12 20h.01',user:'M12 3a4 4 0 1 0 0 8 4 4 0 0 0 0-8 M4 21v-2a8 8 0 0 1 16 0v2',chevron:'M9 5l7 7-7 7',eye:'M2 12s4-7 10-7 10 7 10 7-4 7-10 7-10-7-10-7 M12 9a3 3 0 1 0 0 6 3 3 0 0 0 0-6',photo:'M3 6h4l2-3h6l2 3h4v14H3z M12 9a4 4 0 1 0 0 8 4 4 0 0 0 0-8'};
const icon=name=>`<svg viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[name]||paths.file}"/></svg>`;
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const date=value=>value?new Date(value).toLocaleString(undefined,{dateStyle:'medium',timeStyle:'short'}):'Not yet synced';
const size=value=>value>=1073741824?(value/1073741824).toFixed(1)+' GB':value>=1048576?(value/1048576).toFixed(1)+' MB':Math.ceil((value||0)/1024)+' KB';
const normal=value=>String(value||'').normalize('NFKD').replace(/[\u0300-\u036f]/g,'').toLowerCase();
const tokens=query=>normal(query).trim().split(/\s+/).filter(Boolean);
const terminalTask=status=>['failed','done','installed','removed','superseded'].includes(status);
const sections=[['Home','home','indigo'],['Messages','mail','blue'],['School Notes','book','violet'],['App Store','apps','mint'],['Wallpapers','image','pink'],['Media','folder','amber'],['Downloads','download','blue'],['Background tasks','sync','cyan'],['Support','help','orange'],['Help & guide','book','violet'],['About Device','device','slate']];
function safePhoto(value){return typeof value==='string'&&value.length<=140000&&/^data:image\/(jpeg|png|webp);base64,[A-Za-z0-9+/=]+$/.test(value)?value:null}
function avatar(){const photo=safePhoto(state.student_profile?.profile_photo),initials=(state.student_name||'Student').trim().split(/\s+/).slice(0,2).map(s=>s[0]).join('');return photo?`<img src="${esc(photo)}" alt="Your profile">`:esc(initials)}
function call(action,args={}){if(window.PrimeNative)window.PrimeNative.request(JSON.stringify({action,...args}));else toast('Preview only. This action is available on your Primebook.')}
function toast(text){clearTimeout(toastTimer);const target=document.getElementById('toast');target.textContent=text;target.hidden=false;toastTimer=setTimeout(()=>target.hidden=true,5000)}
function agentAtLeast(major,minor,patch){const current=String(state.agent_version||'0').split('.').map(Number),required=[major,minor,patch];for(let n=0;n<3;n++){const value=Number.isFinite(current[n])?current[n]:0;if(value!==required[n])return value>required[n]}return true}
function primeId(){const value=state.prime_id||state.runtime?.prime_id||state.runtime?.wifi?.prime_id;return typeof value==='string'&&/^([0-9a-f]{2}:){5}[0-9a-f]{2}$/i.test(value)?value.toUpperCase():'Not reported by this device'}
let themeChoice=window.PRIMESECURE_THEME||document.querySelector('meta[name="primesecure-theme"]')?.content||'system';
try{if(!window.PRIMESECURE_THEME&&themeChoice==='system')themeChoice=localStorage.getItem('primesecure-theme')||'system'}catch{}
function applyTheme(value,persist=false){themeChoice=['light','dark','system'].includes(value)?value:'system';document.documentElement.dataset.theme=themeChoice;const dark=themeChoice==='dark'||themeChoice==='system'&&window.matchMedia('(prefers-color-scheme: dark)').matches;document.querySelector('meta[name="theme-color"]')?.setAttribute('content',dark?'#101421':'#f5f7fc');const button=document.getElementById('theme-toggle');if(button){button.innerHTML=icon(dark?'sun':'moon');button.setAttribute('aria-label',`Switch to ${dark?'light':'dark'} mode`);button.title=`Switch to ${dark?'light':'dark'} mode`}if(persist){try{localStorage.setItem('primesecure-theme',themeChoice)}catch{}if(state.capabilities?.theme_preferences===true){themePending=themeChoice;call('theme',{value:themeChoice})}}}
applyTheme(themeChoice);
window.matchMedia('(prefers-color-scheme: dark)').addEventListener?.('change',()=>{if(themeChoice==='system')applyTheme('system')});

function resetWorkspace(){supportReadLocal.clear();draftImages={support:'',bug:''};attachmentTarget='support';clearTimeout(searchTimer);lastTaskRaw='';setMenu(false);view='Home';folder=[];showHidden=false;files=null;noteQuery=appQuery=mediaQuery=globalQuery=helpQuery=helpCategory='';noteForm=noteSubject=noteType=noteAvailability=appFilter='';profilePhoto=null;noteLimit=appLimit=120;lastPageHTML=lastCatalogueKey=lastBannerHTML=activeSignature='';indexedItems=[];taskMap.clear();closeSearch();document.getElementById('app').replaceChildren();document.getElementById('toast').hidden=true}
function catalogueKey(){return JSON.stringify((state.items||[]).map(i=>[i.id,i.title,i.kind,i.updated_at,i.available,i.installed,i.hidden,i.required,i.can_uninstall,i.version_name,i.size,i.form_level,i.subject,i.category,i.storage_path,i.mime_type,i.icon_data?.length,i.preview?.length]))+JSON.stringify(state.hidden_keys||[])}
function rebuildIndex(){const next=catalogueKey();if(next===lastCatalogueKey)return;lastCatalogueKey=next;indexedItems=(state.items||[]).map(item=>({item,text:normal([item.title,item.form_level,item.subject,item.category,item.kind==='resource'?resourcePath(item).join(' '):'',fileType(item),item.mime_type,item.storage_path?.split('/').pop(),item.version_name].filter(Boolean).join(' '))}));}
function rebuildTasks(){taskMap=new Map();for(const task of state.tasks||[]){const id=task.item_id||String(task.key||'').replace(/^(install|uninstall|download):/,'');if(id&&!taskMap.has(id))taskMap.set(id,task)}}
window.receiveState=raw=>{let next;try{next=JSON.parse(raw)}catch{return}if(!next||typeof next!=='object'||Array.isArray(next))return;const nextIdentity=[next.device_id||'',next.student_id||''].join('|');const unavailable=next.enrolled===false||next.is_enrolled===false||next.authenticated===false||next.signed_out===true||next.status==='retired';if(unavailable||identity&&nextIdentity!==identity)resetWorkspace();identity=nextIdentity;received=true;lockedOut=unavailable;state={items:[],messages:[],hidden_keys:[],tasks:[],...next};if(!Array.isArray(state.items))state.items=[];if(!Array.isArray(state.messages))state.messages=[];if(!Array.isArray(state.tasks))state.tasks=[];if(!Array.isArray(state.hidden_keys))state.hidden_keys=[];if(state.ui_theme&&(!themePending||state.ui_theme===themePending)){themePending=null;applyTheme(state.ui_theme)}rebuildIndex();rebuildTasks();render();if(view==='Support')readSupport();call('ui_ready')};
window.receiveFiles=raw=>{if(lockedOut||!received)return;try{files=JSON.parse(raw)}catch{return}if(view==='Media')renderPage(true)};
window.receivePhoto=photo=>{if(lockedOut)return;profilePhoto=safePhoto(photo);const target=document.getElementById('profile-photo');if(target)target.innerHTML=profilePhoto?`<img src="${esc(profilePhoto)}" alt="Your profile">`:icon('user');document.getElementById('profile-form')?.setAttribute('data-dirty','true')};
window.actionFailed=text=>{toast(text);document.querySelectorAll('button[data-submitting]').forEach(button=>{button.disabled=false;delete button.dataset.submitting});document.querySelector('[aria-busy="true"]')?.removeAttribute('aria-busy')};
window.goBack=()=>{if(document.getElementById('global-search')?.open)return closeSearch();if(menuOpen)return setMenu(false);if(view==='School Notes'&&folder.length){folder.pop();updateNoteResults()}else navigate('Home')};
function heading(title,description,extra=''){return `<div class="section-title"><div><h1>${esc(title)}</h1><p class="muted">${esc(description)}</p></div>${extra}</div>`}
function empty(name,text,title='Nothing here yet'){return `<div class="empty"><div class="empty-icon">${icon(name)}</div><h3>${esc(title)}</h3><p>${esc(text)}</p></div>`}
function pendingTasks(){return(state.tasks||[]).filter(t=>!terminalTask(t.status))}
function render(){if(!received){document.getElementById('app').innerHTML=`<main class="launch-screen"><img src="primebook.png" alt="Primebook"><h1>PrimeSecure</h1><div class="loading-dots" aria-hidden="true"><i></i><i></i><i></i></div><p role="status">Opening your school workspace…</p></main>`;return}if(lockedOut){document.getElementById('app').innerHTML=`<main class="launch-screen">${icon('shield')}<h1>School setup required</h1><p>This workspace is no longer enrolled. Please contact your school administrator.</p></main>`;return}if(!document.getElementById('workspace-page'))mountShell();updateShell();renderPage()}
function mountShell(){document.getElementById('app').innerHTML=`<div class="shell"><button class="nav-scrim" id="nav-scrim" aria-label="Close navigation" hidden></button><aside class="sidebar" id="workspace-nav"><div class="brand"><div class="brand-mark"><img src="primebook.png" alt="Primebook"></div><div><b>PrimeSecure</b><small>LEARN · CONNECT · GROW</small></div></div><div class="nav-label">YOUR WORKSPACE</div><nav class="nav-list" aria-label="Workspace">${sections.map(([name,i,color])=>`<button class="nav" data-view="${name}"><span class="nav-icon ${color}">${icon(i)}</span><span>${name}</span><span class="nav-count" data-nav-count="${name}" hidden></span></button>`).join('')}</nav><div class="sidebar-bottom"><button class="support-shortcut" data-view="Support">${icon('help')}<span>Need a hand?<small>Message RoboKorda</small></span>${icon('chevron')}</button><div class="sidebar-footer"><img src="robokorda.jpg" alt="RoboKorda"><span>Your school workspace<br><b>Managed by RoboKorda</b></span></div></div></aside><main class="main"><header class="topbar"><button class="icon-button menu-button" id="menu-toggle" aria-label="Open navigation" aria-expanded="false" aria-controls="workspace-nav">${icon('menu')}</button><div class="school-name"><small>SCHOOL WORKSPACE</small><b id="school-name"></b></div><div class="header-tools"><button class="icon-button" id="open-search" aria-label="Search notes and apps" title="Search notes and apps (Ctrl K)">${icon('search')}</button><button class="icon-button" data-view="Help & guide" aria-label="Open student help and guide" title="Help & guide">${icon('help')}</button><button class="icon-button notification-button" data-view="Notifications" aria-label="Notifications">${icon('mail')}<span id="notification-count" class="nav-count" hidden></span></button><button class="icon-button" id="theme-toggle" aria-label="Switch theme"></button><button class="icon-button sync-button" data-action="sync" aria-label="Sync workspace" title="Sync workspace">${icon('sync')}</button><span class="connection-pill" id="connection-badge"></span><button class="profile-button" data-view="Profile" aria-label="Edit your profile"><span class="identity-text"><b id="student-name"></b><small id="student-class"></small></span><span class="avatar" id="header-avatar"></span></button></div></header><div class="page"><div id="school-sync-banner"></div><section id="workspace-page" tabindex="-1" aria-label="Home"></section><div id="sync-error"></div></div></main></div>`;lastPageHTML='';applyTheme(themeChoice)}
function updateShell(){document.getElementById('school-name').textContent=state.school_name||'Your school';document.getElementById('student-name').textContent=state.student_name||'Student';document.getElementById('student-class').textContent=[state.form_level,state.class_name].filter(Boolean).join(' · ')||state.student_id||'Student';const headerAvatar=document.getElementById('header-avatar');const art=avatar();if(headerAvatar.innerHTML!==art)headerAvatar.innerHTML=art;updateNavigation();updateConnection();const banner=schoolSyncBanner();if(banner!==lastBannerHTML){document.getElementById('school-sync-banner').innerHTML=banner;lastBannerHTML=banner}const error=document.getElementById('sync-error');const text=state.sync_error?`<div class="alert" role="status">${icon('wifi')}<span>${esc(state.sync_error)}</span><button class="button light" data-action="sync">Try again</button></div>`:'';if(error.innerHTML!==text)error.innerHTML=text}
function updateNavigation(){const bell=document.getElementById('notification-count');if(bell){const n=state.messages.filter(m=>!m.seen).length+unreadSupport().length;bell.textContent=n>99?'99+':n;bell.hidden=!n;}const unread=state.messages.filter(m=>!m.seen).length,pending=pendingTasks().length;document.querySelectorAll('.nav').forEach(button=>{const active=button.dataset.view===view;button.classList.toggle('active',active);if(active)button.setAttribute('aria-current','page');else button.removeAttribute('aria-current')});for(const [name,count]of[['Messages',unread],['Support',unreadSupport().length],['Background tasks',pending]]){const el=document.querySelector(`[data-nav-count="${name}"]`);if(el){el.textContent=count;el.hidden=!count}}}
function updateConnection(){const badge=document.getElementById('connection-badge');if(badge){badge.className='connection-pill '+(state.online?'online':'offline');badge.innerHTML=`<i></i>${state.online?'Online':'Offline'}`;badge.title=state.online?'Connected to the internet':'Your saved notes and media remain available'}}
function schoolSyncBanner(){const sync=state.school_sync||{};if(!sync.revision)return '';const pending=sync.revision>sync.applied_revision;if(!pending&&Date.now()-(sync.updated_at||0)>60000)return '';const topics=(sync.topics||[]).map(t=>({apps:'apps',notes:'school notes',wallpapers:'wallpapers',library:'library',settings:'settings'}[t]||'settings')).join(', ');return `<div class="sync-banner ${pending?'pending':'complete'}" role="status">${icon(pending?'sync':'check')}<div><b>${pending?!state.online?'Updates waiting for internet':sync.phase==='attention'?'Some changes need school attention':'Updating your workspace':'Your workspace is up to date'}</b><small>${esc(topics||'School settings')} · ${pending?'You can keep learning. Downloads continue in the background.':'Your saved library stays available offline.'}</small></div><button class="text-button" data-view="Background tasks">View tasks ${icon('arrow')}</button></div>`}
function pageSignature(){const common=[view,lastCatalogueKey,JSON.stringify(state.hidden_keys),state.allow_wallpaper_choice];if(view==='Home')common.push(state.student_name,state.last_sync,JSON.stringify(state.messages),JSON.stringify(state.tasks.map(t=>[t.id,t.status])));if(['School Notes','App Store','Wallpapers'].includes(view))common.push(JSON.stringify(state.tasks.map(t=>[t.id,t.status])));if(view==='School Notes')common.push(JSON.stringify(state.resource_requests));if(view==='Messages')common.push(JSON.stringify(state.messages),JSON.stringify(state.replies));if(['Support','Notifications'].includes(view))common.push(JSON.stringify(state.messages),JSON.stringify(state.support_messages));if(view==='Support')common.push(JSON.stringify(state.support_messages),JSON.stringify(state.pending_support));if(view==='Profile')common.push(JSON.stringify(state.student_profile));if(view==='Downloads')common.push(JSON.stringify(state.download_sites),state.online,state.capabilities?.controlled_downloads);if(view==='About Device')common.push(state.agent_version,state.ui_version,state.installed_apps_count,JSON.stringify(state.support_contacts),JSON.stringify(state.runtime),JSON.stringify(state.device),JSON.stringify(state.battery));if(view==='Background tasks')common.push(JSON.stringify(state.tasks.map(t=>[t.id,t.status,t.title,t.error])));return common.join('|')}
function renderPage(force=false){const page=document.getElementById('workspace-page');if(!page)return;if(!state.student_profile&&view!=='Profile')view='Profile';const signature=pageSignature();if(!force&&signature===activeSignature){patchProgress();return}if(!force&&page.querySelector('form[data-dirty="true"]')){patchProgress();return}const focused=document.activeElement;if(!force&&focused&&page.contains(focused)&&['notes-search','apps-search','media-search','help-search'].includes(focused.id)){if(view==='School Notes')updateNoteResults();if(view==='App Store')document.getElementById('app-results').innerHTML=appResults();if(view==='Media')document.getElementById('media-results').innerHTML=mediaResults();if(view==='Help & guide')updateHelpResults();activeSignature=signature;return}const html=content();if(force||html!==lastPageHTML){page.innerHTML=html;lastPageHTML=html;page.setAttribute('aria-label',view);page.removeAttribute('aria-busy')}activeSignature=signature;updateNavigation()}
function navigate(name){if(lockedOut||!received||!sections.some(s=>s[0]===name)&&!['Profile','Notifications','Report a bug'].includes(name))return;const changed=view!==name;view=name;setMenu(false);closeSearch();updateNavigation();if(changed){lastPageHTML='';activeSignature='';document.getElementById('workspace-page')?.setAttribute('aria-busy','true')}renderPage(true);if(changed)window.scrollTo(0,0);if(name==='Media')call('media');if(name==='Support')readSupport()}
function setMenu(open){menuOpen=open;document.documentElement.classList.toggle('nav-open',open);const scrim=document.getElementById('nav-scrim');if(scrim)scrim.hidden=!open;const button=document.getElementById('menu-toggle');button?.setAttribute('aria-expanded',String(open));button?.setAttribute('aria-label',open?'Close navigation':'Open navigation')}
function content(){switch(view){case'Home':return home();case'Messages':return messages();case'School Notes':return notes();case'App Store':return apps();case'Wallpapers':return wallpapers();case'Media':return media();case'Downloads':return downloadsPage();case'Help & guide':return helpPage();case'Background tasks':return backgroundTasks();case'Support':return support();case'Notifications':return notifications();case'Report a bug':return bugReport();case'Profile':return profilePage();default:return about()}}

function home(){const notes=state.items.filter(i=>i.kind==='resource'),apps=state.items.filter(i=>i.kind==='app'),wallpapers=state.items.filter(i=>i.kind==='wallpaper'),unread=state.messages.filter(m=>!m.seen),saved=notes.filter(i=>i.available),pending=pendingTasks();const shortcuts=[['School Notes','book','violet',`${notes.length} resources`,'Open your learning library'],['Messages','mail','blue',`${unread.length} unread`,'Notices from your school'],['App Store','apps','mint',`${apps.length} approved apps`,'Tools selected for you'],['Media','folder','amber','Your documents & media','Find it. Open it.'],['Wallpapers','image','pink',`${wallpapers.length} backgrounds`,'A little more you'],['About Device','device','cyan','Device & support','Your Primebook at a glance']];return `<div class="home-intro"><div><div class="eyebrow">${new Date().toLocaleDateString(undefined,{weekday:'long',day:'numeric',month:'long'})}</div><h1>My workspace<span class="heading-dot">.</span></h1><p class="muted">${esc(greeting())}</p></div><span class="class-chip">${icon('user')}${esc([state.form_level,state.class_name].filter(Boolean).join(' · ')||state.school_name||'Your school')}</span></div><section class="hero"><div><span class="hero-label">READY WHEN YOU ARE</span><h2>A little curiosity.<br>A whole lot to discover.</h2><p>Your notes, school apps and messages. One familiar place.</p><button class="button white" data-view="School Notes">${icon('book')} Open school notes ${icon('arrow')}</button></div><div class="hero-art" aria-hidden="true"><span class="art-dot one"></span><span class="art-dot two"></span><div class="art-card back">${icon('image')}</div><div class="art-card front">${icon('book')}<i></i><i></i></div><div class="art-bubble">${icon('check')}</div></div></section><div class="quick-stats"><div>${icon('download')}<span><b>${saved.length}<small> / ${notes.length}</small></b><small>Notes saved offline</small></span></div><div>${icon('apps')}<span><b>${apps.filter(i=>i.installed).length}</b><small>School apps installed</small></span></div><button data-view="Background tasks">${icon('sync')}<span><b data-home-pending>${pending.length}</b><small data-home-task-label>${pending.length?'Tasks in progress':'All tasks complete'}</small></span>${icon('chevron')}</button></div><div class="section-line"><h2>Your essentials</h2><span>Made for the school day</span></div><div class="tiles">${shortcuts.map(([name,i,color,count,desc])=>`<button class="tile" data-view="${name}"><span class="icon-box ${color}">${icon(i)}</span><span class="tile-copy"><h3>${name}</h3><p>${desc}</p><small>${count}</small></span>${icon('chevron')}</button>`).join('')}</div><div class="home-columns"><section class="card"><div class="section-line"><h2>From your school</h2><button class="text-button" data-view="Messages">View inbox ${icon('arrow')}</button></div>${state.messages.slice(0,2).map(m=>`<button class="compact-row" data-action="message" data-id="${esc(m.id)}"><span class="mini-icon blue">${icon('mail')}</span><span><b>${esc(m.payload?.title||'Message from school')}</b><small>${date(m.created_at)}</small></span><span class="tiny-dot ${m.seen?'read':''}"></span></button>`).join('')||'<p class="quiet-empty">No messages yet. New school notices will appear here.</p>'}</section><section class="card"><div class="section-line"><h2>Ready offline</h2><button class="text-button" data-view="School Notes">Browse ${icon('arrow')}</button></div>${saved.filter(i=>!resourceHidden(i)).slice(0,2).map(i=>`<button class="compact-row" data-action="resource" data-id="${esc(i.id)}"><span class="mini-icon violet">${icon(fileIcon(i))}</span><span><b>${esc(i.title)}</b><small>${esc(i.subject||'School notes')} · ${size(i.size)}</small></span>${icon('chevron')}</button>`).join('')||'<p class="quiet-empty">Your school resources download in Background tasks while you are online.</p>'}</section></div><div class="workspace-footer">${icon('shield')}<span>Managed by your school · Last check-in ${date(state.last_sync)}</span><button class="text-button" data-view="About Device">What is shared?</button></div>`}
function itemTask(id){return taskMap.get(id)}
function taskLabel(t){if(!t)return '';return({queued:state.online?'Queued':'Waiting for internet',waiting:'Waiting for connection',syncing:t.action==='uninstall'?'Checking removal':'Checking',downloading:'Downloading',installing:'Installing',uninstalling:'Removing',removing:'Removing',installed:'Installed',removed:'Removed',done:'Complete',failed:'Needs attention',superseded:'Replaced by a newer choice'})[t.status]||t.status}
function progress(t){if(!t)return '';const percent=t.total?Math.min(100,Math.floor((t.bytes||0)/t.total*100)):0;return `<div class="task-progress" data-task="${esc(t.id)}"><div class="task-status"><span>${esc(taskLabel(t))}</span>${t.total?`<b>${percent}%</b>`:''}</div><progress max="100" value="${['done','installed','removed'].includes(t.status)?100:percent}" aria-label="${esc(t.title||'Task')} progress"></progress><small>${t.total?size(t.bytes)+' / '+size(t.total):''}${t.speed?' · '+size(t.speed)+'/s':''}</small></div>`}
function patchProgress(){const count=document.querySelector('[data-home-pending]');if(count){const pending=pendingTasks().length;count.textContent=pending;document.querySelector('[data-home-task-label]').textContent=pending?'Tasks in progress':'All tasks complete'}document.querySelectorAll('[data-task]').forEach(el=>{const task=state.tasks.find(t=>t.id===el.dataset.task);if(task){const html=progress(task);if(el.outerHTML!==html)el.outerHTML=html}})}
function resourcePath(i){return[i.form_level||'All levels',i.subject||'General',i.category||'Notes']}
function folderKey(path){return path.length===1?'form:'+path[0]:path.length===2?'subject:'+path.join(':'):'category:'+path.join(':')}
function resourceHidden(i){const path=resourcePath(i);return i.hidden||(state.hidden_keys||[]).includes('item:'+i.id)||path.some((_,n)=>state.hidden_keys.includes(folderKey(path.slice(0,n+1))))}
function fileType(i){const extension=String(i.storage_path||i.title||'').split('.').pop().toLowerCase(),mime=i.mime_type||'';if(extension==='pdf'||mime==='application/pdf')return'PDF';if(['doc','docx','odt','rtf'].includes(extension)||/word|opendocument.text/.test(mime))return'Word';if(extension==='epub')return'Books';if(mime.startsWith('image/')||['jpg','jpeg','png','webp','gif'].includes(extension))return'Images';if(mime.startsWith('video/')||['mp4','mkv','webm','avi'].includes(extension))return'Videos';if(mime.startsWith('audio/')||['mp3','m4a','ogg','wav'].includes(extension))return'Audio';if(['xls','xlsx','csv'].includes(extension)||/spreadsheet/.test(mime))return'Spreadsheets';if(['ppt','pptx','odp'].includes(extension)||/presentation/.test(mime))return'Slides';return'Other'}
function fileIcon(i){return({Images:'image',Videos:'video',Audio:'music',Books:'book'})[fileType(i)]||'file'}
function option(value,label,selected){return `<option value="${esc(value)}"${value===selected?' selected':''}>${esc(label)}</option>`}
function notes(){const resources=state.items.filter(i=>i.kind==='resource'),forms=[...new Set(resources.map(i=>resourcePath(i)[0]))].sort(),subjects=[...new Set(resources.filter(i=>!noteForm||resourcePath(i)[0]===noteForm).map(i=>resourcePath(i)[1]))].sort();return heading('School Notes','Your forms, subjects and resources. Saved notes work offline.',`<button class="button light" id="show-hidden" aria-pressed="${showHidden}">${icon('eye')}${showHidden?'Hide hidden':'Show hidden'}</button>`)+`<div class="library-toolbar"><label class="search-box">${icon('search')}<input id="notes-search" type="search" value="${esc(noteQuery)}" placeholder="Search titles, subjects, forms or file types…" aria-label="Search school notes" autocomplete="off"><kbd>/</kbd></label><div class="filter-row"><label><span>Form</span><select id="notes-form">${option('','All forms',noteForm)}${forms.map(v=>option(v,v,noteForm)).join('')}</select></label><label><span>Subject</span><select id="notes-subject">${option('','All subjects',noteSubject)}${subjects.map(v=>option(v,v,noteSubject)).join('')}</select></label><label><span>File type</span><select id="notes-type">${option('','All file types',noteType)}${['PDF','Word','Books','Images','Videos','Audio','Spreadsheets','Slides','Other'].map(v=>option(v,v,noteType)).join('')}</select></label><label><span>Availability</span><select id="notes-availability">${option('','All resources',noteAvailability)}${option('offline','Saved offline',noteAvailability)}${option('pending','Download pending',noteAvailability)}</select></label><button class="icon-button clear-filters" data-local="clear-notes" aria-label="Clear note search and filters" title="Clear search and filters">${icon('close')}</button></div></div><div id="note-results">${noteResults()}</div>${learningRequests()}`}
function learningRequests(){if(!state.capabilities?.resource_requests)return `<p class="muted">Update PrimeSecure to request learning materials here.</p>`;const subjects=[...new Set(state.items.filter(i=>i.kind==='resource').map(i=>i.subject).filter(Boolean))].sort(),forms=[...new Set([state.form_level,...state.items.filter(i=>i.kind==='resource').map(i=>i.form_level)].filter(Boolean))].sort();return `<details class="card app-request"><summary>${icon('book')}Missing a book or notes? Request learning materials</summary><form id="resource-request" class="reply-form"><label>Material type<select name="resource_type">${['Book','Notes','Past exam papers','Novel','Textbook','Images','Other resources'].map(v=>option(v,v,'Book')).join('')}</select></label><label>Title or topic<input name="name" required maxlength="160" placeholder="e.g. Form 3 Chemistry past papers"></label><label>Form<select name="form_level">${option('','All levels',state.form_level)}${forms.map(v=>option(v,v,state.form_level)).join('')}</select></label><label>Subject<select name="subject">${option('','General','')}${subjects.map(v=>option(v,v,'')).join('')}</select></label><label>Details<textarea name="reason" maxlength="1000" placeholder="Author, exam year, syllabus or topic. For another subject, write its name here."></textarea></label><button class="button">Send request ${icon('arrow')}</button><small class="muted">Offline? Your request is saved in Background tasks and sends when connected.</small></form><div class="request-history"><h3>Your recent requests</h3>${(state.resource_requests||[]).map(r=>`<article class="compact-row"><span class="mini-icon violet">${icon('book')}</span><span><b>${esc(r.name)}</b><small>${esc(r.resource_type)} ? ${date(r.created_at)}</small></span><span class="badge">${esc(r.status)}</span></article>`).join('')||'<p class="muted">No learning requests sent yet.</p>'}</div></details>`}
function noteResults(){const query=tokens(noteQuery),searching=query.length||noteForm||noteSubject||noteType||noteAvailability;const resources=indexedItems.filter(r=>r.item.kind==='resource').filter(({item,text})=>(showHidden||!resourceHidden(item))&&query.every(word=>text.includes(word))&&(!noteForm||resourcePath(item)[0]===noteForm)&&(!noteSubject||resourcePath(item)[1]===noteSubject)&&(!noteType||fileType(item)===noteType)&&(!noteAvailability||(noteAvailability==='offline')===Boolean(item.available))).map(r=>r.item);if(searching){return `<div class="results-line"><span role="status">${resources.length} ${resources.length===1?'resource':'resources'} found</span><span>Searching the whole library</span></div>${resources.length?`<div class="resource-grid">${resources.slice(0,noteLimit).map(resourceCard).join('')}</div>${moreButton(resources.length,noteLimit,'more-notes')}`:empty('search','Try a shorter title, a subject or another file type.','No matching resources')}`}
const filtered=resources.filter(i=>folder.every((name,n)=>resourcePath(i)[n]===name));const crumbs=`<nav class="crumbs" aria-label="School note folders"><button data-crumb="0">${icon('folder')}All forms</button>${folder.map((name,n)=>`${icon('chevron')}<button data-crumb="${n+1}">${esc(name)}</button>`).join('')}</nav>`;if(!filtered.length)return crumbs+empty('book',state.items.some(i=>i.kind==='resource')?'This folder has no visible resources. You can show hidden resources above.':'Your school’s notes and past papers will appear here.','Your library is ready');if(folder.length>=3)return crumbs+`<div class="results-line"><span>${filtered.length} resources</span><span>${filtered.filter(i=>i.available).length} saved offline</span></div><div class="resource-grid">${filtered.slice(0,noteLimit).map(resourceCard).join('')}</div>${moreButton(filtered.length,noteLimit,'more-notes')}`;const groups=new Map();for(const item of filtered){const name=resourcePath(item)[folder.length];if(!groups.has(name))groups.set(name,[]);groups.get(name).push(item)}return crumbs+`<div class="folder-grid">${[...groups].sort(([a],[b])=>a.localeCompare(b,undefined,{numeric:true})).map(([name,items],index)=>{const path=[...folder,name],key=folderKey(path),hidden=state.hidden_keys.includes(key);return `<article class="folder ${hidden?'is-hidden':''}"><button class="folder-open" data-folder="${esc(name)}"><span class="folder-art tone-${index%4}"><span></span>${icon(folder.length===1?'book':'folder')}</span><b>${esc(name)}</b><small>${items.length} resources · ${items.filter(i=>i.available).length} offline</small></button><button class="hide-btn" data-hide="${esc(key)}" data-hidden="${hidden}" aria-label="${hidden?'Restore':'Hide'} ${esc(name)}">${icon('eye')}</button></article>`}).join('')}</div>`}
function resourceCard(i){const type=fileType(i),hidden=resourceHidden(i);return `<article class="resource-card ${hidden?'is-hidden':''}"><div class="resource-top"><span class="file-type ${type==='PDF'?'red':type==='Images'?'pink':'violet'}">${icon(fileIcon(i))}<small>${esc(type)}</small></span><button class="icon-button" data-hide="item:${esc(i.id)}" data-hidden="${Boolean(i.hidden||state.hidden_keys.includes('item:'+i.id))}" aria-label="${i.hidden?'Restore':'Hide'} ${esc(i.title)}">${icon('eye')}</button></div><h3 title="${esc(i.title)}">${esc(i.title)}</h3><p>${esc(resourcePath(i).slice(0,2).join(' · '))}</p><div class="resource-meta"><span>${size(i.size)}</span><span class="offline-dot ${i.available?'ready':''}">${i.available?'Offline ready':'Pending'}</span></div>${itemTask(i.id)&&!terminalTask(itemTask(i.id).status)?progress(itemTask(i.id)):''}<button class="button ${i.available?'light':''}" data-action="resource" data-id="${esc(i.id)}">${icon(i.available?'book':'download')}${i.available?'Open':'Queue download'}</button></article>`}
function moreButton(total,limit,action){return total>limit?`<div class="load-more"><span>Showing ${limit} of ${total}</span><button class="button light" data-local="${action}">Show more</button></div>`:''}
function updateNoteResults(){const target=document.getElementById('note-results');if(target)target.innerHTML=noteResults()}
function apps(){return heading('App Store','Tools selected for your school. Install now, or queue for when you’re online.')+`<div class="store-toolbar"><label class="search-box">${icon('search')}<input id="apps-search" type="search" value="${esc(appQuery)}" placeholder="Search apps or versions…" aria-label="Search approved apps" autocomplete="off"></label><select id="apps-filter" aria-label="Filter approved apps">${option('','All approved apps',appFilter)}${option('available','Available to install',appFilter)}${option('installed','Installed',appFilter)}${option('required','School defaults',appFilter)}</select></div><div id="app-results">${appResults()}</div><details class="card app-request"><summary>${icon('help')}Can’t find an app? Request it</summary><form id="app-request" class="reply-form"><label>App name<input name="name" required maxlength="160" placeholder="What would you like to use?"></label><label>How would it help?<textarea name="reason" maxlength="1000" placeholder="Tell your school what you need it for."></textarea></label><button class="button">Send request ${icon('arrow')}</button></form></details>`}
function appResults(){const query=tokens(appQuery);const items=indexedItems.filter(r=>r.item.kind==='app'&&query.every(word=>normal([r.item.title,r.item.version_name].join(' ')).includes(word))).map(r=>r.item).filter(i=>!appFilter||appFilter==='available'&&!i.installed||appFilter==='installed'&&i.installed||appFilter==='required'&&i.required);return `<div class="results-line"><span role="status">${items.length} ${items.length===1?'app':'apps'}</span><span>Only school-approved apps appear here</span></div>${items.length?`<div class="store-grid">${items.slice(0,appLimit).map(appCard).join('')}</div>${moreButton(items.length,appLimit,'more-apps')}`:empty('apps',state.items.some(i=>i.kind==='app')?'Try another app name or clear the filter.':'Your school will publish approved apps here.','No apps to show')}`}
function appCard(i){const task=itemTask(i.id),pending=task&&!terminalTask(task.status),removable=agentAtLeast(0,7,0)&&state.capabilities?.uninstall_optional_apps===true&&i.installed&&!i.required&&i.can_uninstall===true;return `<article class="store-app" data-app-id="${esc(i.id)}"><div class="store-app-main">${i.icon_data?`<img class="store-icon" src="${esc(i.icon_data)}" alt="" loading="lazy">`:`<span class="store-icon store-placeholder hue-${String(i.title).length%4}">${icon('apps')}</span>`}<div><h3 title="${esc(i.title)}">${esc(i.title)}</h3><p class="store-meta">${i.version_name?'v'+esc(i.version_name)+' · ':''}${size(i.size)}</p>${i.required?'<span class="required-label">School default</span>':i.installed?'<span class="installed-label">Installed</span>':''}</div></div>${pending?progress(task):`<div class="store-actions">${i.installed&&state.capabilities?.open_approved_apps===true?`<button class="button small" data-action="open_app" data-id="${esc(i.id)}" aria-label="Open ${esc(i.title)}">Open</button>`:""}${i.installed?removable?`<button class="text-button" data-action="uninstall" data-id="${esc(i.id)}" aria-label="Uninstall ${esc(i.title)}">Uninstall</button>`:`<span class="installed-check">${icon('check')}Installed</span>`:`<button class="button small" data-action="install" data-id="${esc(i.id)}" aria-label="Install ${esc(i.title)}">${icon('download')}Install</button>`}</div>`}</article>`}

function messages(){return heading('Messages','Your school inbox. Open a notice, acknowledge it and reply.')+(state.messages.length?`<div class="inbox-list">${state.messages.map(m=>`<article class="message card ${m.seen?'':'unread'}"><div class="message-main"><span class="mini-icon blue">${icon('mail')}</span><div><div class="message-title"><h3>${esc(m.payload?.title||'Message from school')}</h3><span class="badge ${m.acknowledged?'green':!m.seen?'blue':''}">${m.acknowledged?'Acknowledged':m.seen?'Seen':'New'}</span></div><small>${esc(m.payload?.from||'School')} · ${date(m.created_at)}</small><p class="message-preview">${esc(String(m.payload?.body||'').slice(0,200))}</p></div></div><div class="message-actions"><button class="button light small" data-action="message" data-id="${esc(m.id)}">Read message ${icon('arrow')}</button>${m.payload?.require_ack&&!m.acknowledged?'<span class="ack-label">Acknowledgement needed</span>':''}</div><details><summary>Reply to your school</summary><form class="reply-form" data-reply="${esc(m.id)}"><label>Your reply<textarea name="body" required maxlength="4000" placeholder="Write your reply…"></textarea></label><label class="check-label"><input type="checkbox" name="anonymous"> Mark this reply anonymous</label><p class="profile-note">School administrators can always see your name. Replies are private to you and school staff; the anonymous label applies to any future student-facing sharing.</p><button class="button">Send reply ${icon('arrow')}</button></form></details>${(state.replies||[]).filter(r=>r.command_id===m.id).map(r=>`<div class="reply-preview"><b>Your reply${r.anonymous?' (anonymous)':''}</b><p>${esc(r.body)}</p><small>${date(r.created_at)}</small></div>`).join('')}</article>`).join('')}</div>`:empty('mail','New notices from your school will appear here.','A quiet inbox'))}
function wallpapers(){const items=state.items.filter(i=>i.kind==='wallpaper');return heading('Wallpapers',`${items.length} school-approved backgrounds. Saved wallpapers apply offline.`)+(!state.allow_wallpaper_choice?'<div class="alert">Your school has set a fixed wallpaper.</div>':'')+`<div class="wallpaper-grid">${items.map(i=>`<article class="wallpaper-card">${i.preview?`<img class="wallpaper" src="${esc(i.preview)}" alt="${esc(i.title)}" loading="lazy">`:`<div class="wallpaper wallpaper-placeholder">${icon('image')}</div>`}<div class="wallpaper-copy"><div><h3>${esc(i.title)}</h3><span class="offline-dot ${i.available?'ready':''}">${i.available?'Saved offline':'Download pending'}</span></div><button class="button small ${i.available?'light':''}" data-action="wallpaper" data-id="${esc(i.id)}" ${!state.allow_wallpaper_choice?'disabled':''}>${i.available?'Use wallpaper':'Download'}</button></div>${itemTask(i.id)&&!terminalTask(itemTask(i.id).status)?progress(itemTask(i.id)):''}</article>`).join('')}</div>`+(!items.length?empty('image','Your school’s approved backgrounds will appear here.','Make room for a fresh view'):'')}
function mediaKind(e){if(e.dir||String(e.name||'').startsWith('.'))return'other';return/\.(jpg|jpeg|png|webp|gif)$/i.test(e.name)?'image':/\.(mp4|webm|mkv|avi)$/i.test(e.name)?'video':/\.(mp3|ogg|m4a|wav|flac)$/i.test(e.name)?'music':/\.(pdf|doc|docx|odt|rtf|txt|epub|xls|xlsx|ppt|pptx)$/i.test(e.name)?'file':'other'}
function media(){return heading('Media','Your documents, pictures, music and videos.',`<button class="button light" data-action="media">${icon('sync')}Refresh</button>`)+`<div class="media-tabs" role="group" aria-label="Media category">${[['file','Documents','violet'],['image','Pictures','pink'],['video','Videos','blue'],['music','Music','mint']].map(([kind,name,color])=>`<button class="${fileKind===kind?'active':''}" data-file-kind="${kind}" aria-pressed="${fileKind===kind}"><span class="mini-icon ${color}">${icon(kind)}</span>${name}<small>${(files?.entries||[]).filter(e=>mediaKind(e)===kind).length}</small></button>`).join('')}</div><label class="search-box media-search">${icon('search')}<input id="media-search" type="search" value="${esc(mediaQuery)}" aria-label="Search media" placeholder="Find a file by name…"></label><div id="media-results">${mediaResults()}</div>`}
function mediaResults(){if(!files)return `<div class="loading-card" role="status"><div class="loading-dots"><i></i><i></i><i></i></div><b>Finding your media…</b><p>All-files access must be enabled on this Primebook.</p></div>`;const query=tokens(mediaQuery),entries=(files.entries||[]).filter(e=>mediaKind(e)===fileKind&&query.every(word=>normal(e.name).includes(word)));return entries.length?`<div class="media-grid">${entries.slice(0,240).map(e=>{const p=e.path||[files.path,e.name].filter(Boolean).join('/'),thumbnail=typeof e.thumbnail==='string'&&/^data:image\/jpeg;base64,[A-Za-z0-9+/=]+$/.test(e.thumbnail);return `<article class="media-card"><button class="media-cover ${fileKind}" data-action="open_file" data-path="${esc(p)}" aria-label="Open ${esc(e.name)}">${thumbnail?`<img src="${esc(e.thumbnail)}" alt="" loading="lazy">`:icon(fileKind)}${fileKind==='video'?`<span class="play-mark">${icon('video')}</span>`:''}</button><div><h3 title="${esc(e.name)}">${esc(e.name)}</h3><small>${size(e.size)}</small><button class="icon-button" data-action="open_file" data-path="${esc(p)}" aria-label="Open ${esc(e.name)}">${icon('arrow')}</button></div></article>`}).join('')}</div>${entries.length>240?'<p class="profile-note">Showing the first 240 files. Search to find any file in this category.</p>':''}`:empty(fileKind,mediaQuery?'Try another file name.':'Matching files saved on your Primebook appear here.','No '+({file:'documents',image:'pictures',video:'videos',music:'music'})[fileKind]+' yet')}
function backgroundTasks(){const tasks=(state.tasks||[]).filter(t=>t.status!=='superseded'),pending=tasks.filter(t=>!terminalTask(t.status)),failed=tasks.filter(t=>t.status==='failed');return heading('Background tasks','Downloads and saved changes continue when internet is available.',`<button class="button light" data-action="sync">${icon('sync')}Sync now</button>`)+`<div class="task-summary"><span class="mini-icon cyan">${icon('sync')}</span><div><b>${pending.length} pending ${pending.length===1?'task':'tasks'}</b><small>${state.online?'Connected. Your queued changes are being processed.':'Offline. Your place is saved; tasks resume when you reconnect.'}</small></div>${failed.length?`<span class="badge amber">${failed.length} need attention</span>`:''}</div>`+(tasks.length?`<div class="task-list">${tasks.map(t=>`<article class="task-card"><span class="mini-icon ${t.status==='failed'?'orange':terminalTask(t.status)?'mint':'cyan'}">${icon(t.action==='install'?'apps':['download','web_download'].includes(t.action)?'download':t.action==='uninstall'?'apps':terminalTask(t.status)?'check':'sync')}</span><div class="task-body"><h3>${esc(t.title)}</h3>${progress(t)}${t.error?`<p class="task-error">${esc(t.error)}</p>`:''}</div>${t.status==='failed'&&t.action!=='admin_command'?`<button class="button light small" data-action="retry_task" data-id="${esc(t.id)}">Retry</button>`:''}</article>`).join('')}</div>`:empty('check','New downloads and offline changes will appear here.','All caught up'))}
function supportPhoto(message){const image=message.attachment_data;return typeof image==='string'&&image.length<=100000&&/^data:image\/jpeg;base64,[A-Za-z0-9+/=]+$/.test(image)?`<details class="support-photo"><summary>View shared photo</summary><img src="${esc(image)}" alt="Photo shared with RoboKorda support" loading="lazy"></details>`:''}

function downloadsPage(){
 const supported=state.capabilities?.controlled_downloads===true;
 const choices=[{id:'music',name:'Music & videos',site:'MP3Juices',icon:'music',color:'violet',text:'Search for music and videos, then save supported files to your Primebook.',detail:'MP3, MP4, M4A, WAV, OGG and WebM · up to 250 MB'},{id:'images',name:'Find a picture',site:'Unsplash',icon:'image',color:'mint',text:'Find photographs for a project, presentation or a little inspiration.',detail:'JPG, PNG, GIF and WebP · up to 25 MB'}];
 return heading('Downloads','A few approved places to find something new.',`<button class="button light" data-view="Help & guide">${icon('help')} How it works</button>`)+
 `<div class="download-sites">${choices.map(choice=>{const site=(state.download_sites||[]).find(s=>s.id===choice.id),approved=supported&&site?.allowed,ready=approved&&state.online;return `<article class="card download-site"><div class="download-site-art ${choice.color}" aria-hidden="true"><span>${icon(choice.icon)}</span><i>${icon('download')}</i></div><div class="download-site-heading"><span class="eyebrow">${esc(choice.site)}</span><span class="badge ${approved?'green':''}">${!supported?'Update needed':approved?'School approved':'Approval needed'}</span></div><h2>${choice.name}</h2><p>${choice.text}</p><small>${choice.detail}</small><button class="button" data-action="open_school_site" data-id="${choice.id}" ${ready?'':'disabled'}>${icon(choice.icon)} ${!supported?'Install the latest PrimeSecure':!approved?'Ask your school to approve':!state.online?'Connect to the internet':'Open '+choice.site} ${icon('arrow')}</button></article>`}).join('')}</div>
 <section class="card download-how"><span class="mini-icon blue">${icon('shield')}</span><div><h2>Your search stays inside the approved site</h2><p>No browser address bar or external windows. Only supported media files can be saved; apps, web pages and other files are blocked.</p><p>Choose the site's actual download button, then confirm <b>Download</b>. Follow its progress in <button class="text-button" data-view="Background tasks">Background tasks</button>. Finished files appear in <button class="text-button" data-view="Media">Media</button>.</p><small>Use school-appropriate material that you have permission to download. Public search results are provided by the website. Unsplash may also show paid content.</small></div></section>
 <div class="download-shortcuts"><button class="card" data-view="Media">${icon('folder')}<span><b>Open saved media</b><small>Keep enjoying it offline</small></span>${icon('chevron')}</button><button class="card" data-view="Background tasks">${icon('sync')}<span><b>Check download progress</b><small>${pendingTasks().length} tasks pending</small></span>${icon('chevron')}</button></div>`;
}

const helpTopics=[
 {group:'Getting started',icon:'home',q:'Where do I start?',a:'Home is your overview. Use the sidebar to open School Notes, Messages, App Store, Media and Support. Your school and profile stay at the top. Complete your profile when asked, and keep at least one parent or guardian phone number up to date.'},
 {group:'School Notes',icon:'book',q:'How do I find and read a book?',a:'Open School Notes, choose a form, then a subject and resource folder. Search by title or topic if you know what you need. A Saved resource is ready to open offline; a downloading resource shows its progress in Background tasks.'},
 {group:'School Notes',icon:'search',q:'A book, past paper or subject is missing. What now?',a:'Use Request learning material in School Notes. Choose the resource type, form and subject, then add the title and a short reason. You can request notes, textbooks, past papers, novels and other resources. Your request saves offline and sends when you reconnect.'},
 {group:'School Notes',icon:'eye',q:'Can I hide notes or folders?',a:'Yes. Hide a resource, subject or form to tidy your own library. This does not delete the school copy. Use Show hidden to bring it back. School-provided learning files are managed by your administrators.'},
 {group:'Apps & media',icon:'apps',q:'Can I install an app that is not in App Store?',a:'Use PrimeSecure App Store for school-approved apps. If an app is missing, send an app request instead of installing files from another source. School defaults cannot be uninstalled; optional approved apps show a Remove option.'},
 {group:'Apps & media',icon:'folder',q:'Where are my documents, pictures, music and videos?',a:'Open Media and choose Documents, Pictures, Music or Videos. Use Refresh after saving a new file. Your school may choose the app used to open each type. If a file will not open, contact Support and include its name.'},
 {group:'Apps & media',icon:'download',q:'How do I download music, videos or pictures?',a:'Open Downloads and choose an approved website. Keep using its own search box; there is no browser address bar. Select the actual download button and confirm Download in PrimeSecure. Check Background tasks, then open the finished file in Media. Images have a 25 MB limit; music and video files have a 250 MB limit. APKs, HTML pages and unsupported files are not accepted.'},
 {group:'Apps & media',icon:'shield',q:'Why does a download link say it is blocked?',a:'Advertisements, outside websites, unapproved download hosts and unsupported file types are blocked. Use the website’s real download button rather than an advert. If the real file still fails, report the problem to Support; do not install another browser or downloader to get around the restriction.'},
 {group:'Connection & device',icon:'wifi',q:'What can I use without internet?',a:'Saved notes, the student guide and media already on your Primebook work offline. Replies, support messages, profile changes and requests can wait in Background tasks until you reconnect. Website searches need an internet connection. Keep Wi-Fi connected so school content and settings can sync.'},
 {group:'Connection & device',icon:'sync',q:'How do I refresh or sync PrimeSecure?',a:'Use the sync button near your profile at the top right. You can keep working while updates arrive. Background tasks shows downloads, installs and saved changes. A task marked Needs attention offers Retry when it can be retried.'},
 {group:'Connection & device',icon:'image',q:'How do I change my wallpaper?',a:'Open Wallpapers and choose a school-approved image. A saved wallpaper can be applied locally without internet. If it is still downloading, wait for it to finish in Background tasks. Your school may set a fixed wallpaper instead.'},
 {group:'Connection & device',icon:'shield',q:'Can I change location, Bluetooth, USB or sharing settings?',a:'These settings are managed by your school. When a feature is restricted, PrimeSecure does not provide a student override. Use school notes and approved apps instead of transferring files between devices. If you need a resource or a sharing method for a lesson, request it through the system or contact Support.'},
 {group:'Messages & privacy',icon:'mail',q:'How do I read, acknowledge and reply to messages?',a:'Open Messages, then Read message. Important notices may ask you to acknowledge them before continuing. Acknowledgement confirms you saw the notice; it is not a reply. You can still find it in your inbox afterwards. New messages and support replies appear in Notifications at the top right.'},
 {group:'Messages & privacy',icon:'user',q:'What does an anonymous reply mean?',a:'You can mark a school-message reply anonymous. Administrators can still see your identity and the anonymous label. It is not a way to hide your identity from staff. Support conversations are private to you and authorised staff, rather than a public student chat.'},
 {group:'Messages & privacy',icon:'shield',q:'Are support messages end-to-end encrypted?',a:'No. Messages use a secure connection, and authorised school or RoboKorda staff can read them to help you. PrimeSecure does not describe this as end-to-end encryption. Only pictures you choose and send are attached to your support messages.'},
 {group:'Messages & privacy',icon:'device',q:'What device information can my school see?',a:'Authorised staff can see device information, installed apps, shared-file inventory, last reported location and Wi-Fi details. App usage is reported when enabled and supported. Camera support asks you to start a session and review what you share.'},
 {group:'Help & repairs',icon:'help',q:'How do I contact Cde Sedze or report a bug?',a:'Open Support and write to the RoboKorda team. For a software problem, choose Report a bug, select a category, explain the steps and attach a screenshot if it helps. Your message saves offline and sends after reconnection. Use Support to reach Cde Sedze and arrange repairs too.'},
 {group:'Help & repairs',icon:'user',q:'Can I change my name or emergency details?',a:'Open your profile at the top right. You can edit your username, date of birth, address, phone numbers and profile picture. Your real name is set by the school; use the name correction request if it is wrong. Profile changes save locally and sync when connected.'},
 {group:'Help & repairs',icon:'device',q:'I forgot my password or my Primebook is not working. Should I reset it?',a:'Contact Support or school IT first. A factory reset erases local information and may remove enrollment. If password recovery was activated, staff may be able to set a temporary password without erasing your files; the device must be reachable. Do not reset it as a first troubleshooting step.'}
];
function helpResults(){const query=helpQuery.trim().toLowerCase(),matches=helpTopics.filter(t=>(!helpCategory||t.group===helpCategory)&&(!query||[t.q,t.a,t.group].join(' ').toLowerCase().includes(query)));return `<div class="help-result-count">${matches.length} ${matches.length===1?'answer':'answers'}${helpCategory?' · '+esc(helpCategory):''}</div>`+(matches.length?`<div class="help-faq">${matches.map(t=>`<details${query?' open':''}><summary><span class="mini-icon violet">${icon(t.icon)}</span><span>${esc(t.q)}<small>${esc(t.group)}</small></span>${icon('chevron')}</summary><p>${esc(t.a)}</p></details>`).join('')}</div>`:empty('search','Try another word, or ask Cde Sedze in Support.','No matching answer'))}
function updateHelpResults(){const result=document.getElementById('help-results');if(result)result.innerHTML=helpResults()}
function helpNotesPicture(){return `<svg class="help-illustration" viewBox="0 0 580 245" role="img" aria-label="Illustrated guide: choose School Notes, open Form 1 and Robotics, then open a saved resource"><defs><marker id="help-arrow" markerWidth="7" markerHeight="7" refX="6" refY="3.5" orient="auto"><path d="M0 0 7 3.5 0 7" fill="var(--accent)" stroke="none"/></marker></defs><rect x="10" y="10" width="560" height="225" rx="18" fill="var(--panel)" stroke="var(--line)"/><rect x="10" y="10" width="136" height="225" rx="18" fill="var(--soft)" stroke="none"/><g fill="var(--muted)" stroke="none" font-size="13"><text x="28" y="45">Your workspace</text><text x="28" y="82">Home</text><text x="28" y="116">Messages</text><rect x="20" y="133" width="118" height="32" rx="8" fill="var(--accent-soft)"/><text x="28" y="154" fill="var(--accent)" font-weight="bold">School Notes</text><text x="28" y="190">App Store</text><text x="172" y="44">School Notes</text><text x="172" y="75" fill="var(--accent)">Form 1 → Robotics</text></g><rect x="172" y="93" width="172" height="118" rx="12" fill="var(--violet-bg)" stroke="none"/><path d="M192 124v-10h31l8 10h83v55H192z" fill="var(--violet)" stroke="none" opacity=".7"/><text x="192" y="198" fill="var(--text)" stroke="none" font-size="12">Practical handouts</text><rect x="367" y="93" width="178" height="118" rx="12" fill="var(--green-bg)" stroke="none"/><g fill="var(--text)" stroke="none" font-size="12"><text x="382" y="121">LED circuits</text><text x="382" y="145" fill="var(--green)">✓ Saved on this device</text><text x="382" y="190" fill="var(--accent)" font-weight="bold">Read resource →</text></g><path d="M115 150C155 150 143 122 180 128M329 151h32" stroke="var(--accent)" stroke-width="2.5" marker-end="url(#help-arrow)" fill="none"/></svg>`}
function helpPage(){
 const groups=[...new Set(helpTopics.map(t=>t.group))];
 const repairs=[['Screen replacement',50],['Motherboard',50],['Battery',40],['Keyboard',40],['Touchpad',40],['Speakers',20]];
 return `<div class="help-welcome"><div><span class="eyebrow">YOUR STUDENT GUIDE</span><h1>A little help, right here<span class="heading-dot">.</span></h1><p>Find your way around PrimeSecure, get answers and look after your Primebook.</p></div><span class="help-welcome-icon" aria-hidden="true">${icon('book')}</span></div>
 <div class="help-quick-links"><button data-view="School Notes">${icon('book')}School Notes</button><button data-view="Downloads">${icon('download')}Downloads</button><button data-view="Support">${icon('help')}Ask Cde Sedze</button><button data-view="Report a bug">${icon('shield')}Report a problem</button></div>
 <div class="help-tutorials"><section class="card help-tutorial"><div class="help-card-title"><span class="mini-icon violet">${icon('book')}</span><div><h2>Find a book. Make it yours.</h2><small>School Notes → Form → Subject → Resource</small></div></div>${helpNotesPicture()}<p>Choose a folder or use search. Look for <b>Saved</b> to keep learning offline. Missing something? Send a learning material request.</p><button class="text-button" data-view="School Notes">Open School Notes ${icon('arrow')}</button></section><section class="card help-tutorial"><div class="help-card-title"><span class="mini-icon mint">${icon('download')}</span><div><h2>From a search to your Media</h2><small>Only school-approved websites and media files</small></div></div><ol class="help-steps"><li><span class="mini-icon violet">${icon('search')}</span><div><b>1. Choose an approved site</b><small>Open Downloads, then search inside the website.</small></div>${icon('arrow')}</li><li><span class="mini-icon blue">${icon('download')}</span><div><b>2. Choose the real download</b><small>Confirm Download when PrimeSecure asks.</small></div>${icon('arrow')}</li><li><span class="mini-icon cyan">${icon('sync')}</span><div><b>3. Follow Background tasks</b><small>Progress, connection status and Retry live here.</small></div>${icon('arrow')}</li><li><span class="mini-icon mint">${icon('folder')}</span><div><b>4. Open it in Media</b><small>Pictures, music and videos stay available offline.</small></div>${icon('check')}</li></ol><button class="text-button" data-view="Downloads">Find something to download ${icon('arrow')}</button></section></div>
 <section class="help-answers"><div class="help-section-heading"><h2>Questions, answered</h2><span class="badge">${helpTopics.length} helpful answers</span></div><div class="help-search-row"><label class="search-box">${icon('search')}<input id="help-search" type="search" value="${esc(helpQuery)}" placeholder="Ask about notes, passwords, downloads…" aria-label="Search the student guide"></label><label class="sr-only" for="help-category">Help topic</label><select id="help-category"><option value="">All topics</option>${groups.map(g=>`<option value="${esc(g)}" ${g===helpCategory?'selected':''}>${esc(g)}</option>`).join('')}</select></div><div id="help-results">${helpResults()}</div></section>
 <section class="card repair-card"><div class="help-section-heading"><div><span class="eyebrow">LOOKING AFTER YOUR PRIMEBOOK</span><h2>Repairs & replacement</h2><p>Contact Cde Sedze through Support to arrange a repair.</p></div><span class="badge">Prices in USD</span></div><div class="repair-grid"><div class="repair-table-wrap"><table class="repair-table"><thead><tr><th>Repair</th><th>Price</th></tr></thead><tbody>${repairs.map(([name,price])=>`<tr><td>${name}</td><td>$${price}</td></tr>`).join('')}</tbody></table><p class="repair-note">${icon('device')} Charging port problems: the motherboard is replaced. Charging ports are not repaired separately.</p></div><aside class="new-primebook"><span class="mini-icon blue">${icon('device')}</span><span>New Primebook</span><strong>$250<small> USD</small></strong><p>Ask your support team about a replacement.</p><button class="button" data-view="Support">Message Cde Sedze ${icon('arrow')}</button></aside></div></section>`;
}
function support(){const pending=state.pending_support||[],modern=state.capabilities?.communication_inbox===true,capture=agentAtLeast(0,7,0)&&state.capabilities?.support_photo===true;return heading('RoboKorda support','Messages, shared images and help from your school team.',`<button class="button light" data-view="Report a bug">${icon('help')} Report a bug</button>`)+`<div class="support-layout"><section class="card support-chat"><div class="chat-heading"><span class="mini-icon violet">${icon('help')}</span><span><b>RoboKorda support</b><small>Saved offline, sent when connected</small></span></div><div class="chat-thread">${(state.support_messages||[]).map(m=>`<div data-support-id="${esc(m.id)}" class="chat-bubble ${m.sender==='student'?'mine':''}"><b>${m.sender==='student'?'You':'RoboKorda'}${m.category==='bug_report'?' ? Bug report':m.category==='name_correction'?' ? Name correction':''}</b><p class="${m.deleted_at?'deleted-message':''}">${esc(m.body)}</p>${!m.deleted_at?supportPhoto(m):''}<small>${date(m.created_at)}${m.category==='bug_report'&&!m.deleted_at?' ? '+esc(m.report_status||'open'):''}</small>${modern&&m.sender==='student'&&!m.deleted_at?`<button class="icon-button delete-support" data-action="support_delete" data-id="${esc(m.id)}" aria-label="Delete your message">${icon('close')}</button>`:''}</div>`).join('')}${pending.map(m=>`<div class="chat-bubble mine pending"><b>You</b><p>${esc(m.body)}</p><small>${icon('clock')} ${esc(m.status==='failed'?'Could not send; check Background tasks':m.status)}</small></div>`).join('')}${!state.support_messages?.length&&!pending.length?empty('help','Write a message or report a problem.','How can we help?'):''}</div><form id="support-form" class="reply-form chat-compose"><label class="sr-only" for="support-body">Message RoboKorda</label><textarea id="support-body" name="body" required maxlength="4000" placeholder="Write a message to support?"></textarea>${attachmentControls('support',modern)}<div class="compose-actions">${capture?`<button type="button" class="icon-button" data-action="support_photo" aria-label="Share a photo with support" title="Open camera and preview a photo">${icon('photo')}</button>`:''}<span class="profile-note">Only images you select and send are shared.</span><button class="button">Send ${icon('arrow')}</button></div></form></section><aside class="card support-contacts"><h2>Your support team</h2>${(state.support_contacts||[]).map(c=>`<div class="support-row"><span class="avatar">${esc(String(c.name||'R')[0])}</span><div><b>${esc(c.name)}</b><small>${esc(c.phone)}</small></div></div>`).join('')}<button class="button light" data-view="Report a bug">Report a bug or error</button><p class="profile-note">Choose a category, describe the steps and attach a screenshot if it helps.</p></aside></div>`}

function searchResults(){const query=tokens(globalQuery),matches=query.length?indexedItems.filter(r=>['resource','app'].includes(r.item.kind)&&(r.item.kind!=='resource'||!resourceHidden(r.item))&&query.every(word=>r.text.includes(word))).slice(0,18):[];const target=document.getElementById('global-search-results');if(!target)return;target.innerHTML=!query.length?'<p class="search-hint">Search resource titles, subjects, forms, file types or app names.</p>':matches.length?matches.map(({item})=>`<button class="search-result" data-search-item="${esc(item.id)}"><span class="mini-icon ${item.kind==='app'?'mint':'violet'}">${icon(item.kind==='app'?'apps':fileIcon(item))}</span><span><b>${esc(item.title)}</b><small>${esc(item.kind==='app'?'App · '+(item.version_name||'School approved'):resourcePath(item).join(' · '))}</small></span>${icon('chevron')}</button>`).join(''):empty('search','Try a subject, a shorter title or an app name.','No matches')}
function openSearch(){if(!received||lockedOut)return;const dialog=document.getElementById('global-search');if(dialog.open)return;dialog.showModal();globalQuery='';document.getElementById('global-search-input').value='';searchResults();document.getElementById('global-search-input').focus()}
function closeSearch(){document.getElementById('global-search')?.close();globalQuery='';const results=document.getElementById('global-search-results');if(results)results.replaceChildren()}

document.addEventListener('click',event=>{const button=event.target.closest('button, [data-hide]');if(!button)return;if(button.id==='theme-toggle'){const dark=themeChoice==='dark'||themeChoice==='system'&&matchMedia('(prefers-color-scheme: dark)').matches;return applyTheme(dark?'light':'dark',true)}if(button.id==='menu-toggle')return setMenu(!menuOpen);if(button.id==='nav-scrim')return setMenu(false);if(button.id==='open-search')return openSearch();if(button.id==='close-search')return closeSearch();if(lockedOut||!received)return;if(button.dataset.view)return navigate(button.dataset.view);if(button.dataset.searchItem){const item=state.items.find(i=>i.id===button.dataset.searchItem);closeSearch();if(item?.kind==='resource')return call('resource',{id:item.id});if(item?.kind==='app'){appQuery=item.title;appFilter='';return navigate('App Store')}}if(button.dataset.local==='attach'){attachmentTarget=button.dataset.target||'support';return call('choose_attachment')}if(button.dataset.local==='remove-attachment'){draftImages[button.dataset.target||'support']='';return updateAttachmentPreview()}if(button.dataset.action==='support_delete'){if(!confirm('Delete this message and its image for both sides?'))return;const m=(state.support_messages||[]).find(m=>m.id===button.dataset.id);if(m){m.deleted_at='pending';m.body='Deleting message?';m.attachment_data=null;}call('support_delete',{id:button.dataset.id});return renderPage(true)}if(button.dataset.action){if(button.disabled)return;call(button.dataset.action,{id:button.dataset.id,path:button.dataset.path});if(button.dataset.action==='sync'){button.classList.add('sync-requested');toast('Sync requested. Your saved workspace is still available.');setTimeout(()=>button.classList.remove('sync-requested'),1200)}return}if(button.dataset.folder){folder.push(button.dataset.folder);noteLimit=120;return updateNoteResults()}if(button.hasAttribute('data-crumb')){folder=folder.slice(0,Number(button.dataset.crumb));noteLimit=120;return updateNoteResults()}if(button.dataset.hide){const value=button.dataset.hidden!=='true';state.hidden_keys=value?[...new Set([...state.hidden_keys,button.dataset.hide])]:state.hidden_keys.filter(k=>k!==button.dataset.hide);const item=state.items.find(i=>'item:'+i.id===button.dataset.hide);if(item)item.hidden=value;call('hide',{key:button.dataset.hide,value});rebuildIndex();return updateNoteResults()}if(button.id==='show-hidden'){showHidden=!showHidden;return renderPage(true)}if(button.dataset.fileKind){fileKind=button.dataset.fileKind;mediaQuery='';renderPage(true);if(files===null)call('media');return}if(button.dataset.local==='clear-notes'){noteQuery=noteForm=noteSubject=noteType=noteAvailability='';noteLimit=120;return renderPage(true)}if(button.dataset.local==='more-notes'){noteLimit+=120;return updateNoteResults()}if(button.dataset.local==='more-apps'){appLimit+=120;document.getElementById('app-results').innerHTML=appResults()}});
document.addEventListener('input',event=>{const target=event.target;if(target.closest('form'))target.closest('form').dataset.dirty='true';if(target.id==='global-search-input'){globalQuery=target.value;return searchResults()}if(target.id==='help-search'){helpQuery=target.value;return updateHelpResults()}if(target.id==='notes-search'){noteQuery=target.value;noteLimit=120;clearTimeout(searchTimer);searchTimer=setTimeout(updateNoteResults,60)}if(target.id==='apps-search'){appQuery=target.value;appLimit=120;clearTimeout(searchTimer);searchTimer=setTimeout(()=>{const results=document.getElementById('app-results');if(results)results.innerHTML=appResults()},60)}if(target.id==='media-search'){mediaQuery=target.value;const results=document.getElementById('media-results');if(results)results.innerHTML=mediaResults()}});
document.addEventListener('change',event=>{const target=event.target;if(target.id==='help-category'){helpCategory=target.value;return updateHelpResults()}if(target.id==='notes-form'){noteForm=target.value;noteSubject='';return renderPage(true)}if(target.id==='notes-subject')noteSubject=target.value;else if(target.id==='notes-type')noteType=target.value;else if(target.id==='notes-availability')noteAvailability=target.value;else if(target.id==='apps-filter'){appFilter=target.value;appLimit=120;document.getElementById('app-results').innerHTML=appResults();return}else return;noteLimit=120;updateNoteResults()});
document.addEventListener('submit',event=>{const form=event.target;if(!form.matches('form'))return;event.preventDefault();if(lockedOut)return;const data=new FormData(form);if(form.dataset.reply){call('reply',{id:form.dataset.reply,body:data.get('body'),anonymous:data.get('anonymous')==='on'});form.reset();delete form.dataset.dirty;return toast('Reply saved. It will send when connected.')}if(form.id==='resource-request'){call('request_resource',{name:data.get('name'),reason:data.get('reason'),resource_type:data.get('resource_type'),form_level:data.get('form_level'),subject:data.get('subject')});form.reset();delete form.dataset.dirty;return toast('Learning request saved. It will send when connected.')}if(form.id==='app-request'){call('request_app',{name:data.get('name'),reason:data.get('reason')});form.reset();delete form.dataset.dirty;return toast('Your app request has been saved.')}if(form.id==='profile-form'){const profile=Object.fromEntries(data);if(!String(profile.mother_phone||'').trim()&&!String(profile.father_phone||'').trim())return toast('Enter at least one parent or guardian phone number.');profile.profile_photo=profilePhoto||'';state.student_profile=profile;call('profile',{profile});delete form.dataset.dirty;return navigate('Home')}if(form.id==='support-form'||form.id==='name-appeal'||form.id==='bug-report-form'){const bug=form.id==='bug-report-form',target=bug?'bug':'support';const payload={body:data.get('body'),image:draftImages[target]||''};if(bug)payload.details={category:data.get('category'),steps:data.get('steps'),expected:data.get('expected'),actual:data.get('actual'),agent_version:state.agent_version||'',ui_version:String(state.ui_version||'')};call(bug?'bug_report':form.id==='name-appeal'?'name_appeal':state.capabilities?.communication_inbox?'support_post':'support',payload);form.reset();delete form.dataset.dirty;draftImages[target]='';updateAttachmentPreview();return toast(bug?'Bug report saved. It will send when connected.':'Message saved. It will send when connected.')}if(form.id==='password-form'){if(data.get('password')!==data.get('confirmation'))return toast('The passwords do not match.');call('device_password',{password:data.get('password')});form.reset();delete form.dataset.dirty}});
document.addEventListener('keydown',event=>{const editing=event.target.matches('input,textarea,select,[contenteditable]');if((event.ctrlKey||event.metaKey)&&event.key.toLowerCase()==='k'){event.preventDefault();openSearch()}else if(event.key==='Escape'){setMenu(false);closeSearch()}else if(event.key==='/'&&!editing){event.preventDefault();document.getElementById(view==='App Store'?'apps-search':view==='Media'?'media-search':'notes-search')?.focus()}if(document.getElementById('global-search')?.open&&event.key==='ArrowDown'&&event.target.id==='global-search-input'){event.preventDefault();document.querySelector('.search-result')?.focus()}});
document.getElementById('global-search').addEventListener('click',event=>{if(event.target===event.currentTarget)closeSearch()});
window.receiveTasks=(raw,online)=>{if(lockedOut||!received||raw===lastTaskRaw&&online===state.online)return;let tasks;try{tasks=JSON.parse(raw)}catch{return}if(!Array.isArray(tasks))return;const onlineChanged=online!==state.online;const changed=JSON.stringify(state.tasks.map(t=>[t.id,t.status]))!==JSON.stringify(tasks.map(t=>[t.id,t.status]));lastTaskRaw=raw;state.tasks=tasks;state.online=online;rebuildTasks();updateConnection();updateNavigation();if(view==='App Store'&&changed){for(const el of document.querySelectorAll('[data-app-id]')){const item=state.items.find(i=>i.id===el.dataset.appId);if(item)el.outerHTML=appCard(item)}}else if(view==='Background tasks'&&changed||view==='Downloads'&&(changed||onlineChanged))renderPage(true);else patchProgress()};

function about(){const d=state.device||{},battery=state.battery||{};return heading('Your Primebook','Device information and people who can help.')+`<div class="two-col"><section class="card"><div class="icon-box blue">${icon('device')}</div><h2 style="margin-top:18px">Device details</h2><dl class="definition">${[['Student',state.student_name],['Student number',state.student_id],['Form / class',[state.form_level,state.class_name].filter(Boolean).join(' / ')],['Prime ID',primeId()],['Model',d.model],['Serial',d.serial],['Android',d.os_version],['PrimeSecure version',state.agent_version||'0.6.0'],['Interface version',state.ui_version||7],['Installed apps',state.installed_apps_count??'Unavailable'],['Battery',d.battery_level!=null?d.battery_level+'%':'Unavailable'],['Reported health',battery.health||'Unavailable'],['Temperature',battery.temperature_c!=null?battery.temperature_c+' °C':'Unavailable'],['Last check-in',date(state.last_sync)]].map(([k,v])=>`<dt>${esc(k)}</dt><dd>${esc(v??'Not provided')}</dd>`).join('')}</dl><p class="profile-note">Android’s health label does not measure battery wear or prove that a battery needs replacement.</p></section><section class="card"><div class="icon-box teal">${icon('help')}</div><h2 style="margin-top:18px">RoboKorda support</h2><p class="muted">Need a hand? Contact our team.</p>${(state.support_contacts||[]).map(c=>`<div class="support-row"><div class="avatar">${esc(c.name[0])}</div><div><b>${esc(c.name)}</b><p>${esc(c.phone)}</p></div></div>`).join('')}<button class="button light" data-action="pin">Request desktop shortcut</button><p class="profile-note" style="margin-top:14px">Your current Primebook launcher decides where shortcuts appear and whether they can be removed.</p><div class="actions"><button class="button" data-view="Support">Message RoboKorda</button><button class="button light" data-view="Profile">Edit profile</button></div></section></div>${storagePanel()}${usagePanel()}${recoveryPanel()}`}

function profilePage(){const p=state.student_profile||{};profilePhoto=safePhoto(p.profile_photo);return `<div class="profile-shell">${heading('Your profile','Your name is set by your school. You can update your personal and emergency details offline.',`<button class="button light" data-action="sync">${icon('sync')} Sync</button>`)}<section class="card"><form id="profile-form" class="profile-form"><div class="full photo-picker"><div class="avatar large" id="profile-photo">${profilePhoto?`<img src="${esc(profilePhoto)}" alt="Your profile">`:icon('image')}</div><button type="button" class="button light" data-action="photo">Choose profile picture</button><span class="muted">Add a photo so your school can recognise you. You can also do this later.</span></div><label>Real name<input readonly value="${esc(state.student_name||'Assigned by school')}"></label><label>Username<input name="username" maxlength="40" pattern="[A-Za-z0-9_.-]{3,40}" value="${esc(p.username)}" placeholder="Choose a username"></label><label>Date of birth<input type="date" name="dob" required min="1900-01-01" max="${new Date().toISOString().slice(0,10)}" value="${esc(p.dob)}"></label><label>Student number<input readonly value="${esc(state.student_id||'Assigned by school')}"></label><label class="full">Home address<textarea name="home_address" required minlength="3" maxlength="1000">${esc(p.home_address)}</textarea></label><label>Mother / guardian phone<input type="tel" name="mother_phone" maxlength="40" value="${esc(p.mother_phone)}"></label><label>Father / guardian phone<input type="tel" name="father_phone" maxlength="40" value="${esc(p.father_phone)}"></label><label class="full">Your phone number (optional)<input type="tel" name="personal_phone" maxlength="40" value="${esc(p.personal_phone)}"></label><p class="profile-note full">Provide at least one parent or guardian phone number. Changes save on this Primebook first and sync securely when internet returns.</p><button class="button full">Save & continue ${icon('arrow')}</button></form><details style="margin-top:24px"><summary>Ask your school to correct your real name</summary><form id="name-appeal" class="reply-form"><textarea name="body" required maxlength="4000" placeholder="Explain the correction your name needs."></textarea><button class="button light">Send correction request</button></form></details></section></div>`}

function storagePanel(){const s=state.runtime?.storage||{},categories=Object.entries(s.categories||{}).sort((a,b)=>b[1]-a[1]);return `<section class="card" style="margin-top:24px"><h2>Storage</h2><p>${size(s.used)} used | ${size(s.free)} free of ${size(s.total)}</p><progress max="${s.total||1}" value="${s.used||0}" aria-label="Storage used"></progress><div class="stats">${categories.map(([k,v])=>`<div class="stat"><span>${esc(k)}</span><b>${size(v)}</b></div>`).join('')}</div><p class="profile-note">Shared-file categories are a partial inventory; apps, protected files and Android occupy additional space. Downloaded school content: ${size(s.school_content)}.</p></section>`}

function recoveryPanel(){const status=state.runtime?.recovery||'not_enabled';return `<section class="card" style="margin-top:24px"><h2>Device password & recovery</h2><p class="muted">Recovery: <b>${esc(({ready:'Ready',not_enabled:'Not enabled',needs_confirmation:'Confirm your current password',unsupported:'Not supported by this device'})[status]||status)}</b></p><p class="profile-note">Enable recovery while you can still unlock this Primebook. Your school can then set a temporary password without erasing your files. Recovery requires a connection. Before-first-unlock recovery: ${state.runtime?.recovery_before_unlock?'registered':'connect once after activation to register'}. PrimeOS support must be tested on your device.</p><button class="button light" data-action="recovery">Enable / confirm recovery</button><form id="password-form" class="reply-form"><label>New device password<input type="password" name="password" required minlength="6" maxlength="64" autocomplete="new-password"></label><label>Confirm password<input type="password" name="confirmation" required minlength="6" maxlength="64" autocomplete="new-password"></label><button class="button">Set device password</button></form></section>`}

function usagePanel(){
 const usage=state.runtime?.usage||{},supported=agentAtLeast(0,7,0)&&state.capabilities?.usage_access_setup===true;
 return `<section class="card reporting-panel" style="margin-top:24px"><div class="icon-box blue">${icon('shield')}</div><h2 style="margin-top:18px">School management & activity reports</h2><p class="muted">Your school manages the apps and content on this Primebook. Administrators can see its installed apps, shared-file inventory, last reported location and connected Wi-Fi details.</p><p class="muted">${usage.enabled?'School activity reporting is enabled. It reports which apps are used and for how long, plus device activity totals.':'App activity reporting is not currently enabled by your school.'} These reports do not collect your private messages, document contents, keystrokes, microphone audio or camera pictures.</p>${supported&&usage.enabled?`<div class="actions"><span class="badge ${usage.usage_access?'green':''}">${usage.usage_access?'Android usage access enabled':'Android usage access needed'}</span>${!usage.usage_access?'<button class="button light" data-action="usage_access">Set up Android usage access</button>':''}</div><p class="profile-note">Android asks you to grant usage access before app activity can be reported.</p>`:''}</section>`;
}


const greetings=["Good day, {name}. Your next discovery starts here.", "Welcome back, {name}. Let’s make today count.", "{name}, remember to check your school messages.", "Keep going, {name}. Small steps make real progress.", "Hello, {name}. What will you learn today?", "{name}, your RoboKorda support team is here to help.", "A fresh page awaits, {name}.", "{name}, curiosity is a wonderful place to start.", "Good to see you, {name}. Explore your notes today.", "{name}, take your learning one step at a time.", "You have room to grow, {name}.", "{name}, a good question can open a new door.", "Make time for something new, {name}.", "{name}, check your inbox before you get started.", "Your learning space is ready, {name}.", "{name}, practise today and build confidence tomorrow.", "Welcome, {name}. There’s something here for you.", "{name}, take a break when you need one.", "One idea can spark another, {name}.", "{name}, try a different way when something feels difficult.", "Your next chapter is waiting, {name}.", "{name}, find your subjects in School Notes.", "Have a thoughtful day, {name}.", "{name}, learning takes patience. Keep at it.", "Hello, {name}. Your school community is cheering you on.", "{name}, remember that asking for help is a strength.", "A little practice goes a long way, {name}.", "{name}, open a book and see where it takes you.", "Welcome home to your workspace, {name}.", "{name}, the RoboKorda team wishes you a good day.", "Ready to explore, {name}?", "{name}, your downloaded notes are ready even offline.", "You can start again, {name}. Every attempt teaches you.", "{name}, make space for creativity today.", "Keep your questions coming, {name}.", "{name}, celebrate something you learned today.", "Your ideas matter, {name}.", "{name}, keep your emergency details up to date.", "Good day, {name}. Let’s explore a new topic.", "{name}, a focused few minutes can make a difference.", "Learn at your own pace, {name}.", "{name}, your next favourite subject might surprise you.", "Welcome back, {name}. Check what’s new in your notes.", "{name}, progress comes from showing up.", "Enjoy your learning journey, {name}.", "{name}, look for the lesson in every challenge.", "A bright idea starts with curiosity, {name}.", "{name}, send RoboKorda a message if you need support.", "Make today a day of discovery, {name}.", "{name}, learn, connect and grow."];
function greeting(){const name=state.student_name||"Student";const seed=[...name].reduce((n,c)=>n+c.charCodeAt(0),0);return greetings[(Math.floor(Date.now()/60000)+seed)%greetings.length].replaceAll("{name}",name)}

render();

function unreadSupport(){return (state.support_messages||[]).filter(m=>m.sender==='support'&&!m.read&&!m.deleted_at&&!supportReadLocal.has(m.id))}
function readSupport(){if(!state.capabilities?.communication_inbox||document.visibilityState==='hidden')return;const visible=new Set([...document.querySelectorAll('[data-support-id]')].map(el=>el.dataset.supportId));const ids=unreadSupport().filter(m=>visible.has(m.id)).map(m=>m.id).slice(0,200);if(!ids.length)return;ids.forEach(id=>supportReadLocal.add(id));call('support_read',{ids});updateNavigation()}
window.openSupport=()=>navigate('Support');
window.receiveAttachment=image=>{if(lockedOut||!received)return;if(typeof image!=='string'||image.length>100000||!/^data:image\/jpeg;base64,[A-Za-z0-9+/=]+$/.test(image))return toast('Choose a smaller image.');draftImages[attachmentTarget]=image;updateAttachmentPreview()};
function attachmentControls(target,enabled){return enabled?`<div class="attachment-controls"><button type="button" class="button light small" data-local="attach" data-target="${target}">${icon('image')} Attach image / screenshot</button><small class="muted">Take a screenshot on your Primebook, then select it here. Images are resized for upload.</small><div data-attachment-preview="${target}">${attachmentPreview(target)}</div></div>`:''}
function attachmentPreview(target){const image=draftImages[target];return image?`<div class="attachment-preview"><img src="${esc(image)}" alt="Image ready to send"><button type="button" class="button light small" data-local="remove-attachment" data-target="${target}">Remove image</button></div>`:''}
function updateAttachmentPreview(){document.querySelectorAll('[data-attachment-preview]').forEach(el=>{el.innerHTML=attachmentPreview(el.dataset.attachmentPreview)})}
function bugReport(){const modern=state.capabilities?.communication_inbox===true;return heading('Report a bug','Help us fix problems you notice in PrimeSecure.',`<button class="button light" data-view="Support">${icon('back')} Support</button>`)+(modern?`<section class="card bug-report"><form id="bug-report-form" class="profile-form"><label>Problem category<select name="category" aria-label="Problem category" required><option value="">Choose a category</option>${[['app','App Store / installs'],['notes','School Notes'],['wallpapers','Wallpapers'],['messages','Messages / support'],['media','Media / viewers'],['network','Connection / syncing'],['enrollment','Enrollment / profile'],['other','Something else']].map(([value,label])=>`<option value="${value}">${label}</option>`).join('')}</select></label><label>Short summary<input name="body" required maxlength="200" placeholder="What went wrong?"></label><label class="full">Steps to reproduce<textarea name="steps" required maxlength="2000" placeholder="1. I opened? 2. I clicked?"></textarea></label><label>What did you expect?<textarea name="expected" maxlength="1000"></textarea></label><label>What actually happened?<textarea name="actual" maxlength="1000"></textarea></label><div class="full">${attachmentControls('bug',true)}</div><p class="profile-note full">The report includes your PrimeSecure and interface versions. Only the image you select is shared. Reports save offline and send after reconnection.</p><button class="button">Send bug report ${icon('arrow')}</button></form></section>`:empty('help','Install PrimeSecure 0.8.1 or newer to send structured reports and screenshots. You can still send a support message.','Update needed'))}
function notifications(){const items=[...state.messages.filter(m=>!m.seen).map(m=>({id:m.id,title:m.payload?.title||'Message from school',body:m.payload?.body||'',time:m.created_at,kind:'notice'})),...unreadSupport().map(m=>({id:m.id,title:'RoboKorda replied',body:m.body,time:m.created_at,kind:'support'}))].sort((a,b)=>String(b.time).localeCompare(String(a.time)));return heading('Notifications','New school messages and support replies.')+(items.length?`<section class="card notification-list">${items.map(m=>`<article><span class="mini-icon blue">${icon(m.kind==='notice'?'mail':'help')}</span><div><b>${esc(m.title)}</b><p>${esc(m.body.slice(0,150))}</p><small>${date(m.time)}</small></div>${m.kind==='notice'?`<button class="button light small" data-action="message" data-id="${esc(m.id)}">Open</button>`:'<button class="button light small" data-view="Support">Read reply</button>'}</article>`).join('')}</section>`:empty('check','New messages and support replies will appear here.','You?re all caught up'))}
document.addEventListener('visibilitychange',()=>{if(view==='Support')readSupport()});
